public class Solution {
    // SPEC: return the LAST index where target appears, or -1
    public static int lastIndex(int[] arr, int target) {
        for (int i = arr.length - 1; i >= 0; i--) {
            if (arr[i] == target) {
                return i;
            }
        }
        return -1;
    }
}

